export function sampleArea(
  pixels: Uint8ClampedArray,
  cx: number,
  cy: number,
  w: number,
  h: number,
): number {
  let sum = 0;
  let count = 0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const sx = Math.max(0, Math.min(w - 1, cx + dx));
      const sy = Math.max(0, Math.min(h - 1, cy + dy));
      const offset = (sy * w + sx) * 4;
      sum += (pixels[offset] + pixels[offset + 1] + pixels[offset + 2]) / 3;
      count++;
    }
  }
  return sum / count;
}

points.forEach((p, i) => {
  const cx = Math.min(Math.floor((p.x / 100) * w), w - 1);
  const cy = Math.min(Math.floor((p.y / 100) * h), h - 1);
  const intensity = sampleArea(pixels, cx, cy, w, h);
  const diff = Math.abs(intensity - calibrationData[i]);
  const isActive = diff > threshold;

  if (isActive && !activeKeysRef.current.has(p.note) && !force) {
    const lastEvent = lastEventTimes.current[p.note] || 0;
    if (time - lastEvent > debounceSec) {
      setMidiEvents((prev) => [...prev, { note: p.note, time, type: 'on' }]);
      activeKeysRef.current.add(p.note);
      lastEventTimes.current[p.note] = time;
    }
  } else if (!isActive && activeKeysRef.current.has(p.note) && !force) {
    const lastEvent = lastEventTimes.current[p.note] || 0;
    if (time - lastEvent > debounceSec) {
      setMidiEvents((prev) => [...prev, { note: p.note, time, type: 'off' }]);
      activeKeysRef.current.delete(p.note);
      lastEventTimes.current[p.note] = time;
    }
  }
});
